import type { Guide } from "./GuidePage";

type GuideInput = Omit<Guide, "heroSteps" | "sectionEyebrow" | "exampleEyebrow" | "ctaTitle" | "ctaText"> & Partial<Pick<Guide, "heroSteps" | "sectionEyebrow" | "exampleEyebrow" | "ctaTitle" | "ctaText">>;

function defineGuide(input: GuideInput): Guide {
  return {
    ...input,
    heroSteps: input.heroSteps ?? input.checks.slice(0, 3).map((check) => [check.title, check.text] as [string, string]),
    sectionEyebrow: input.sectionEyebrow ?? "A practical review",
    exampleEyebrow: input.exampleEyebrow ?? "An illustrative example",
    ctaTitle: input.ctaTitle ?? "Start with your own lease language.",
    ctaText: input.ctaText ?? "Upload a readable signed lease for a free preview. Add an annual CAM or NNN statement if you have one, then decide whether a full report would help organize your questions.",
  };
}

const related = (href: string, title: string, text: string) => ({ href, title, text });
const check = (title: string, text: string, source: string) => ({ title, text, source });
const faq = (question: string, answer: string) => ({ question, answer });
